from torch.utils.cpp_extension import load_inline
conv_transpose3d_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>
#define RTW 4
#define RTH 2
__device__ __forceinline__ int floordiv_pos(int a, int b) {
    int q = a / b;
    int r = a % b;
    if (r != 0 && ((r < 0) != (b < 0))) q--;
    return q;
}
__global__ void conv_transpose3d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    const int batch_size,
    const int in_channels,
    const int out_channels,
    const int D_in, const int H_in, const int W_in,
    const int D_out, const int H_out, const int W_out,
    const int K,
    const int stride,
    const int padding,
    const int groups,
    const int in_channels_per_group,
    const int out_channels_per_group,
    const bool has_bias,
    const int TD, const int TH, const int TW,
    const int max_in_d, const int max_in_h, const int max_in_w)
{
    extern __shared__ float smem[];
    const int KKK = K * K * K;
    float* smem_weight = smem;
    float* smem_input = smem + KKK;
    const int boc = blockIdx.z;
    const int b = boc / out_channels;
    const int oc = boc % out_channels;
    const int g = oc / out_channels_per_group;
    const int oc_local = oc % out_channels_per_group;
    const int ic_start = g * in_channels_per_group;
    const int block_threads = blockDim.x * blockDim.y * blockDim.z;
    const int tid_flat = (threadIdx.z * blockDim.y + threadIdx.y) * blockDim.x + threadIdx.x;
    const int num_h_tiles = (H_out + TH - 1) / TH;
    const int d_tile_idx = blockIdx.y / num_h_tiles;
    const int h_tile_idx = blockIdx.y % num_h_tiles;
    const int w_tile_idx = blockIdx.x;
    const int od0 = d_tile_idx * TD;
    const int oh0 = h_tile_idx * TH;
    const int ow0 = w_tile_idx * TW;
    const int od = od0 + threadIdx.z;
    const int oh_base = oh0 + threadIdx.y * RTH;
    const int ow_base = ow0 + threadIdx.x * RTW;
    const int id_lo = floordiv_pos(od0 + padding - (K - 1), stride);
    const int ih_lo = floordiv_pos(oh0 + padding - (K - 1), stride);
    const int iw_lo = floordiv_pos(ow0 + padding - (K - 1), stride);
    int oh_vals[RTH];
    int ow_vals[RTW];
    bool valid_out[RTH][RTW];
    bool any_valid = false;
    #pragma unroll
    for (int h = 0; h < RTH; h++) {
        oh_vals[h] = oh_base + h;
    }
    #pragma unroll
    for (int r = 0; r < RTW; r++) {
        ow_vals[r] = ow_base + r;
    }
    #pragma unroll
    for (int h = 0; h < RTH; h++) {
        #pragma unroll
        for (int r = 0; r < RTW; r++) {
            valid_out[h][r] = (od < D_out) && (oh_vals[h] < H_out) && (ow_vals[r] < W_out);
            any_valid = any_valid || valid_out[h][r];
        }
    }
    const int tile_vol = max_in_d * max_in_h * max_in_w;
    __syncthreads();
    float sum[RTH][RTW];
    #pragma unroll
    for (int h = 0; h < RTH; h++) {
        #pragma unroll
        for (int r = 0; r < RTW; r++) sum[h][r] = 0.0f;
    }
    // Loop over input channels: for each channel, cooperatively stage the
    // reusable spatial input tile for this output tile into shared memory
    // once, then have all threads in the tile reuse it (structural CTA
    // spatial tiling + shared-memory input reuse). Each thread computes
    // RTH x RTW output points (2D register blocking) to reuse fetched
    // weight values across both the height and width register-blocked
    // outputs, reducing per-output overhead further than 1D blocking.
    for (int ic_local = 0; ic_local < in_channels_per_group; ic_local++) {
        int ic = ic_start + ic_local;
        const float* input_bc = input + ((long)b * in_channels + ic) * D_in * H_in * W_in;
        for (int i = tid_flat; i < KKK; i += block_threads) {
            smem_weight[i] = weight[((long)ic * out_channels_per_group + oc_local) * KKK + i];
        }
        for (int i = tid_flat; i < tile_vol; i += block_threads) {
            int iw_off = i % max_in_w;
            int tmp = i / max_in_w;
            int ih_off = tmp % max_in_h;
            int id_off = tmp / max_in_h;
            int id = id_lo + id_off;
            int ih = ih_lo + ih_off;
            int iw = iw_lo + iw_off;
            float val = 0.0f;
            if (id >= 0 && id < D_in && ih >= 0 && ih < H_in && iw >= 0 && iw < W_in) {
                val = input_bc[(long)id * H_in * W_in + ih * W_in + iw];
            }
            smem_input[i] = val;
        }
        __syncthreads();
        if (any_valid) {
            const float* weight_c = smem_weight;
            for (int kd = 0; kd < K; kd++) {
                int id_val = od + padding - kd;
                if (id_val % stride != 0) continue;
                int id = id_val / stride;
                if (id < 0 || id >= D_in) continue;
                int id_off = id - id_lo;
                if (id_off < 0 || id_off >= max_in_d) continue;
                for (int kh = 0; kh < K; kh++) {
                    int ih_off_arr[RTH];
                    bool ih_valid_arr[RTH];
                    #pragma unroll
                    for (int h = 0; h < RTH; h++) {
                        int ih_val = oh_vals[h] + padding - kh;
                        bool ok = (ih_val % stride == 0);
                        int ih = ih_val / stride;
                        ok = ok && (ih >= 0 && ih < H_in);
                        int ih_off = ih - ih_lo;
                        ok = ok && (ih_off >= 0 && ih_off < max_in_h);
                        ih_valid_arr[h] = ok;
                        ih_off_arr[h] = ok ? ih_off : 0;
                    }
                    const int base_row = id_off * max_in_h;
                    for (int kw = 0; kw < K; kw++) {
                        float w_val = weight_c[kd * K * K + kh * K + kw];
                        #pragma unroll
                        for (int h = 0; h < RTH; h++) {
                            if (!ih_valid_arr[h]) continue;
                            const int base_off = (base_row + ih_off_arr[h]) * max_in_w;
                            #pragma unroll
                            for (int r = 0; r < RTW; r++) {
                                if (!valid_out[h][r]) continue;
                                int iw_val = ow_vals[r] + padding - kw;
                                if (iw_val % stride != 0) continue;
                                int iw = iw_val / stride;
                                if (iw < 0 || iw >= W_in) continue;
                                int iw_off = iw - iw_lo;
                                if (iw_off < 0 || iw_off >= max_in_w) continue;
                                float in_val = smem_input[base_off + iw_off];
                                sum[h][r] += in_val * w_val;
                            }
                        }
                    }
                }
            }
        }
        __syncthreads();
    }
    #pragma unroll
    for (int h = 0; h < RTH; h++) {
        #pragma unroll
        for (int r = 0; r < RTW; r++) {
            if (valid_out[h][r]) {
                float out_val = sum[h][r];
                if (has_bias) {
                    out_val += bias[oc];
                }
                long out_idx = ((long)boc * D_out + od) * H_out * W_out + (long)oh_vals[h] * W_out + ow_vals[r];
                output[out_idx] = out_val;
            }
        }
    }
}
torch::Tensor conv_transpose3d_cuda(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride,
    int padding,
    int output_padding,
    int groups,
    bool has_bias)
{
    input = input.contiguous();
    weight = weight.contiguous();
    if (has_bias) {
        bias = bias.contiguous();
    }
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int D_in = input.size(2);
    const int H_in = input.size(3);
    const int W_in = input.size(4);
    const int out_channels_per_group = weight.size(1);
    const int K = weight.size(2);
    const int out_channels = out_channels_per_group * groups;
    const int in_channels_per_group = in_channels / groups;
    const int D_out = (D_in - 1) * stride - 2 * padding + K + output_padding;
    const int H_out = (H_in - 1) * stride - 2 * padding + K + output_padding;
    const int W_out = (W_in - 1) * stride - 2 * padding + K + output_padding;
    auto output = torch::empty({batch_size, out_channels, D_out, H_out, W_out}, input.options());
    const int TD = 8, TH = 8, TW = 8;
    const int max_in_d = (TD - 1 + K - 1) / stride + 2;
    const int max_in_h = (TH - 1 + K - 1) / stride + 2;
    const int max_in_w = (TW - 1 + K - 1) / stride + 2;
    const int num_h_tiles = (H_out + TH - 1) / TH;
    const int num_d_tiles = (D_out + TD - 1) / TD;
    const int num_w_tiles = (W_out + TW - 1) / TW;
    dim3 block(TW / RTW, TH / RTH, TD);
    dim3 grid((unsigned int)num_w_tiles, (unsigned int)(num_d_tiles * num_h_tiles), (unsigned int)(batch_size * out_channels));
    const int KKK = K * K * K;
    const size_t weight_bytes = (size_t)KKK * sizeof(float);
    const size_t input_tile_bytes = (size_t)max_in_d * max_in_h * max_in_w * sizeof(float);
    const size_t smem_size = weight_bytes + input_tile_bytes;
    if (smem_size > 48 * 1024) {
        cudaFuncSetAttribute(conv_transpose3d_kernel, cudaFuncAttributeMaxDynamicSharedMemorySize, (int)smem_size);
    }
    const float* bias_ptr = has_bias ? bias.data_ptr<float>() : nullptr;
    conv_transpose3d_kernel<<<grid, block, smem_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        D_in, H_in, W_in,
        D_out, H_out, W_out,
        K,
        stride,
        padding,
        groups,
        in_channels_per_group,
        out_channels_per_group,
        has_bias,
        TD, TH, TW,
        max_in_d, max_in_h, max_in_w
    );
    return output;
}
